class Solution:
    def minTimeToVisitAllPoints(self, points: List[List[int]]) -> int:
        res = 0
        x, y = points[0]
        for i in range(1, len(points)):
            x1, y1 = points[i]
            res += max(abs(x-x1), abs(y-y1))
            x, y = x1, y1
        return res

class Solution:
    def climbStairs(self, n: int) -> int:
        dp = [0]*(n+2)
        dp[1] = 1
        dp[2] = 2
        for i in range(3, n+1):
            dp[i] = dp[i-2]+dp[i-1]
        return dp[n]

class Solution:
    def findDisappearedNumbers(self, nums: List[int]) -> List[int]:
        ans = []
        l = len(nums)
        s = set(nums)
        for i in range(1, l+1):
            if i not in s:
                ans.append(i)
        return ans

class Solution:
    def smallerNumbersThanCurrent(self, nums: List[int]) -> List[int]:
        ans = []
        s = sorted(list(nums))
        d = {}
        for i, v in enumerate(s):
            if v not in d:
                d[v] = i
        for i in nums:
            ans.append(d[i])
        return ans

class Solution:
    def sortedSquares(self, nums: List[int]) -> List[int]:
        answer = []
        l, r = 0, len(nums)-1
        while l <= r:
            left, right = abs(nums[l]), abs(nums[r])
            if left > right:
                answer.append(left**2)
                l+=1
            else:
                answer.append(right**2)
                r-=1
        return answer[::-1]

class Solution:
    def spiralOrder(self, matrix: List[List[int]]) -> List[int]:
        ans = []
        while matrix:
            #1
            ans += matrix.pop(0)
            #2
            if matrix and matrix[0]:
                for r in matrix:
                    ans.append(r.pop())
            #3 
            if matrix and matrix[-1]:
                ans += matrix.pop()[::-1]
            #4
            if matrix and matrix[-1]:
                for r in matrix[::-1]:
                    ans.append(r.pop(0))
        return ans

class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        l = len(nums)
        dic = {nums[i]:i for i in range(l)}
        for i in range(l):
            t = target - nums[i]
            if t in dic and dic[t] != i:
                return [i, dic[t]]

class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        xor = 0
        for i in nums:
            xor ^= i
        return xor

class Solution:
    def maxSubArray(self, nums: List[int]) -> int:
        for i in range(1, len(nums)):
            if nums[i-1] > 0:
                nums[i] += nums[i-1]
        return max(nums)

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        memo = [float("inf") for i in range(amount + 1)]
        memo[0] = 0

        for i in range(1, amount + 1):
            for j in range(len(coins)):
                if (coins[j] <= i):
                    c = memo[i - coins[j]]
                    if (c != float("inf") and c + 1 < memo[i]):
                        memo[i] = c + 1
        if memo[amount] == float("inf"):
            return -1
        return memo[amount]

class Solution:
    def containsNearbyDuplicate(self, nums: List[int], k: int) -> bool:
        seen = set()
        for i, v in enumerate(nums):
            if v in seen:
                return True
            seen.add(v)
            if len(seen) > k:
                seen.remove(nums[i-k])
        return False

class Solution:
    def minSubArrayLen(self, target: int, nums: List[int]) -> int:
        l = 0
        ans = float("inf")
        total = 0
        for i in range(len(nums)):
            total += nums[i]
            while total >= target:
                ans = min(ans, i-l+1)
                total -= nums[l]
                l+=1
        return 0 if ans == float("inf") else ans

class Solution:
    def threeSum(self, nums: List[int]) -> List[List[int]]:
        triplet = []
        nums.sort()

        for i, v in enumerate(nums):
            if i > 0 and v == nums[i-1]:
                continue

            l = i+1
            r = len(nums)-1

            while l < r:
                curr_sum = v + nums[l] + nums[r]

                if curr_sum > 0:
                    r -= 1

                elif curr_sum < 0:
                    l += 1

                else:
                    triplet.append([v, nums[l], nums[r]])
                    l += 1

                    while l < r and nums[l] == nums[l-1]:
                        l+=1
        return triplet

class Solution:
    def missingNumber(self, nums: List[int]) -> int:
        return sum(range(len(nums)+1)) - sum(nums)

class Solution:
    def containsDuplicate(self, nums: List[int]) -> bool:
        return len(nums) != len(set(nums))

class Solution:
    def minimumAbsDifference(self, arr: List[int]) -> List[List[int]]:
        arr.sort()
        mn = float("inf")
        for i in range(1, len(arr)):
            mn = min(mn, arr[i] - arr[i-1])
        ans = []
        for i in range(1, len(arr)):
            if arr[i] - arr[i-1] == mn:
                ans.append([arr[i-1], arr[i]])
        return ans

class Solution:
    def longestMountain(self, arr: List[int]) -> int:
        ans = 0
        i = 1
        ln = len(arr)-1
        while i < ln:
            if arr[i-1] < arr[i] > arr[i+1]:
                l = r = i

                while l > 0 and arr[l] > arr[l-1]:
                    l-=1
                while r < ln and arr[r] > arr[r+1]:
                    r+=1
                ans = max(ans, r-l+1)
                i = r
            else:
                i += 1 
        return ans
